import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

const Navigation = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const navItems = [
    { path: '/profile', label: 'Profile', icon: '👤' },
    { path: '/upload', label: 'Upload Bill', icon: '📄' },
    { path: '/budget', label: 'Trip Budget', icon: '🧳' },
    { path: '/team-bills', label: 'Team Bills', icon: '📊' },
  ];

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  return (
    <nav className="modern-navigation">
      {/* Desktop Navigation */}
      <div className="nav-container">
        <div className="nav-brand" onClick={() => navigate('/upload')}>
          <div className="brand-logo">
            <span className="brand-icon">🚀</span>
            <span className="brand-text">PRixGEn</span>
          </div>
          <span className="brand-subtitle">AI Expense Manager</span>
        </div>
        
        <div className="nav-menu">
          {navItems.map((item) => (
            <button
              key={item.path}
              className={`nav-item ${location.pathname === item.path ? 'active' : ''}`}
              onClick={() => navigate(item.path)}
            >
              <span className="nav-icon">{item.icon}</span>
              <span className="nav-label">{item.label}</span>
            </button>
          ))}
          
          <div className="nav-divider"></div>
          
          <button className="nav-logout" onClick={handleLogout}>
            <span className="logout-icon">🚪</span>
            <span className="logout-text">Logout</span>
          </button>
        </div>

        {/* Mobile Menu Button */}
        <button 
          className={`mobile-menu-toggle ${isMobileMenuOpen ? 'active' : ''}`}
          onClick={toggleMobileMenu}
          aria-label="Toggle mobile menu"
        >
          <span className="hamburger-line"></span>
          <span className="hamburger-line"></span>
          <span className="hamburger-line"></span>
        </button>
      </div>

      {/* Mobile Navigation */}
      <div className={`mobile-menu ${isMobileMenuOpen ? 'open' : ''}`}>
        <div className="mobile-menu-content">
          {navItems.map((item) => (
            <button
              key={item.path}
              className={`mobile-nav-item ${location.pathname === item.path ? 'active' : ''}`}
              onClick={() => {
                navigate(item.path);
                setIsMobileMenuOpen(false);
              }}
            >
              <span className="mobile-nav-icon">{item.icon}</span>
              <span className="mobile-nav-label">{item.label}</span>
            </button>
          ))}
          
          <div className="mobile-nav-divider"></div>
          
          <button className="mobile-logout" onClick={handleLogout}>
            <span className="mobile-logout-icon">🚪</span>
            <span className="mobile-logout-text">Logout</span>
          </button>
        </div>
      </div>
    </nav>
  );
};

export default Navigation;
